import { getAllComponents, getSgdsComponents } from "../shared.mjs";
import { expect } from "@open-wc/testing";

/**
 * Verifies the metadata that scripts/makeReact.mjs turns into the React wrappers for sgds-data-table.
 * Reads the custom-elements.json generated by `pnpm build`, so it is skipped when the manifest has not been built.
 */
describe("React wrapper metadata for sgds-data-table", () => {
  let components;

  before(async function () {
    const response = await fetch("/custom-elements.json");
    if (!response.ok) {
      this.skip();
      return;
    }
    components = getSgdsComponents(getAllComponents(await response.json()));
  });

  const reactEvents = component =>
    Object.fromEntries((component.events || []).map(event => [event.reactName, event.name]));

  it("maps the data mode events of SgdsDataTable to React handlers", () => {
    const dataTable = components.find(component => component.tagName === "sgds-data-table");
    expect(dataTable, "sgds-data-table declaration").to.exist;
    expect(reactEvents(dataTable)).to.include({
      onSgdsSort: "sgds-sort",
      onSgdsFilter: "sgds-filter",
      onSgdsPageChange: "sgds-page-change",
      onSgdsSelectionChange: "sgds-selection-change",
      onSgdsRowSelect: "sgds-row-select"
    });
  });

  it("generates a React wrapper for SgdsDataTableColumn", () => {
    const column = components.find(component => component.tagName === "sgds-data-table-column");
    expect(column, "sgds-data-table-column declaration").to.exist;
    expect(column.name).to.equal("SgdsDataTableColumn");
    expect(column.modulePath).to.equal("src/components/DataTable/sgds-data-table-column.ts");
  });
});
